// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;

    function setUp() public {
        c = new FlashGovernanceArbiter(address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address actor, address target, uint256 amount, uint256 unlockTime, uint256 assetSeed) public {
        // keep the input domain wide but meaningful
        vm.assume(actor != address(0) && target != address(0));
        amount = bound(amount, 1, type(uint128).max);
        unlockTime = bound(unlockTime, 0, type(uint64).max);
        assetSeed = bound(assetSeed, 0, 1e30);

        address asset = address(new __InvMutHandleStub());

        // ---- legitimately place a pending decision via the public path ----
        // configure flash governance (caller is not a DAO proposal, so use setDAO to make it honored?)
        // The onlySuccessfulProposal requires !configured || successfulProposal(sender);
        // configured is false, so any sender passes. Good.
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        // The stub DAO must let assertGovernanceApproved through: msg.sender must be DAO or governed.
        // c.DAO() == stub; prank as the stub to call assertGovernanceApproved.
        address daoAddress = c.DAO();
        vm.prank(daoAddress);
        c.assertGovernanceApproved(actor, target, true);

        // at this point pendingFlashDecision[target][actor] has asset/amount/unlockTime (plus current block.timestamp)
        // Read the actual stored decision (don't assume the arithmetic)
        (uint256 pAmount, uint256 pUnlock, address pAsset, ) = c.pendingFlashDecision(target, actor);

        // Only test the interesting case: decision was actually set with future unlock
        vm.assume(pAmount > 0);

        // Ensure we test the pre-unlock boundary the reference reverts on, the bug lets through.
        // Move time so that pUnlock > block.timestamp (future unlock).
        if (pUnlock <= block.timestamp) {
            vm.warp(pUnlock == 0 ? 1 : pUnlock - 1);
        }
        vm.assume(pUnlock > block.timestamp);

        // ---- deciding call: must REVERT on reference (early withdraw), must NOT revert on mutant ----
        // actor is the original msg.sender of the flash decision; call withdraw as actor.
        bool ok;
        vm.prank(actor);
        try c.withdrawGovernanceAsset(target, pAsset) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: before unlockTime, withdrawGovernanceAsset must fail.
        assertTrue(!ok, "withdrawGovernanceAsset succeeded before unlockTime");
    }
}

